from PIL import Image
import numpy as np
for name in ['composite.png','preview.png']:
 a=np.array(Image.open(name))[:260,:260,:3]
 m=(a[:,:,0]>180)&(a[:,:,1]<130)&(a[:,:,2]<130)
 seen=set(); out=[]
 for y,x in zip(*np.where(m)):
  if (y,x) in seen: continue
  todo=[(y,x)]; seen.add((y,x)); c=[]
  while todo:
   p=todo.pop();c.append(p)
   for dy in [-1,0,1]:
    for dx in [-1,0,1]:
     q=(p[0]+dy,p[1]+dx)
     if 0<=q[0]<260 and 0<=q[1]<260 and m[q] and q not in seen: seen.add(q);todo.append(q)
  if len(c)>5:
   ys,xs=zip(*c);out.append((len(c), min(xs),min(ys),max(xs),max(ys)))
 print(name,sorted(out,reverse=True))
